WITH valid AS (SELECT *, UPPER(promo_code) AS promo_code_upper, COALESCE(channel, 'NONE') AS resolved_channel FROM promotions WHERE promo_code IN ('SPRING10', 'WELCOME5')), kept_keys AS (SELECT id, channel FROM valid EXCEPT DISTINCT SELECT id, channel FROM promotions WHERE discount_pct > 0.23), verified AS (SELECT s.* FROM valid s INNER JOIN kept_keys k ON s.id = k.id AND s.channel = k.channel), with_window AS (SELECT s.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM verified s LEFT JOIN promotions pr ON s.channel <=> pr.channel AND s.ends_on BETWEEN pr.starts_on AND pr.ends_on), scored AS (SELECT id, promo_code, starts_on, ends_on, promo_code_upper, resolved_channel, promotion_promo_code, promotion_discount_pct, MIN(discount_pct) OVER (PARTITION BY channel) AS channel_min_discount_pct, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY promo_code), 4) AS discount_pct_share, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY promo_code), 4) AS discount_pct_share_2, DENSE_RANK() OVER w_hist AS discount_pct_dense_rank, DENSE_RANK() OVER (PARTITION BY promotion_promo_code, promo_code ORDER BY promotion_discount_pct NULLS FIRST) AS promotion_discount_pct_dense_rank FROM with_window WINDOW w_hist AS (PARTITION BY channel ORDER BY discount_pct DESC)), filtered AS (SELECT promo_code, starts_on, ends_on, resolved_channel, promotion_promo_code, promotion_discount_pct, channel_min_discount_pct, discount_pct_share, discount_pct_share_2, promotion_discount_pct_dense_rank, CASE WHEN promo_code = 'SPRING10' THEN 1 ELSE 0 END AS is_spring10 FROM scored WHERE ends_on >= TO_DATE('2023-06-01') AND channel_min_discount_pct = 0), enriched AS (SELECT *, RANK() OVER (PARTITION BY promotion_promo_code, promo_code ORDER BY is_spring10 DESC) AS is_spring10_rank, DENSE_RANK() OVER (PARTITION BY promo_code ORDER BY promotion_discount_pct_dense_rank DESC) AS promotion_discount_pct_dense_rank_dense_rank, MIN(is_spring10) OVER (PARTITION BY promotion_promo_code) AS promotion_promo_code_min_is_spring10, CUME_DIST() OVER (ORDER BY channel_min_discount_pct DESC NULLS LAST) AS channel_min_discount_pct_cume_dist, SUM(discount_pct_share_2) OVER (PARTITION BY promo_code, promotion_promo_code) AS promo_code_sum_discount_pct_share_2 FROM filtered), valid_promotions AS (SELECT promo_code, starts_on, ends_on, promotion_promo_code, promotion_discount_pct, channel_min_discount_pct, discount_pct_share_2, promotion_discount_pct_dense_rank, is_spring10_rank, promotion_discount_pct_dense_rank_dense_rank, promotion_promo_code_min_is_spring10, promo_code_sum_discount_pct_share_2, CASE WHEN channel_min_discount_pct_cume_dist >= 0.76 THEN 'High' WHEN channel_min_discount_pct_cume_dist >= 0.22 THEN 'Medium' ELSE 'Low' END AS channel_min_discount_pct_cume_dist_band FROM enriched WHERE ends_on >= TO_DATE('2023-08-31') AND promotion_promo_code IS NOT DISTINCT FROM 'BUNDLE') SELECT promo_code, starts_on, ends_on, promotion_promo_code, channel_min_discount_pct, discount_pct_share_2, promotion_discount_pct_dense_rank, is_spring10_rank, channel_min_discount_pct_cume_dist_band FROM valid_promotions;
